package com.unimend.motonav;

import android.app.*;
import android.content.*;
import android.hardware.*;
import android.location.*;
import android.os.*;
import android.view.Surface;
import android.view.WindowManager;
import java.util.concurrent.*;
import org.json.*;

public class NavForegroundService extends Service implements LocationListener,SensorEventListener {
    static final String START="com.unimend.motonav.START_NAV",STOP="com.unimend.motonav.STOP_NAV";
    private static final String CHANNEL="moto_nav_active"; private static final int NOTICE=91;
    private LocationManager locations; private SensorManager sensors; private Sensor rotationSensor; private Location lastLocation; private float sensorBearing=Float.NaN,targetBearing=Float.NaN,displayBearing=Float.NaN; private long sensorTime; private final Handler animation=new Handler(Looper.getMainLooper()); private final ExecutorService io=Executors.newSingleThreadExecutor(); private long lastWidget,lastScene,lastReroute; private int offRouteFixes;
    private final Runnable headingFrame=new Runnable(){@Override public void run(){if(!Float.isNaN(targetBearing)&&!Float.isNaN(displayBearing)){float delta=angleDelta(displayBearing,targetBearing);if(Math.abs(delta)>.7f){displayBearing=(displayBearing+delta*.42f+360)%360;new NavSessionStore(NavForegroundService.this).bearing(displayBearing);NavWidget.publish(NavForegroundService.this);}}animation.postDelayed(this,350);}};
    @Override public void onCreate(){super.onCreate();locations=(LocationManager)getSystemService(LOCATION_SERVICE);sensors=(SensorManager)getSystemService(SENSOR_SERVICE);rotationSensor=sensors.getDefaultSensor(Sensor.TYPE_ROTATION_VECTOR);NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CHANNEL,"导航进行中",NotificationManager.IMPORTANCE_LOW));}
    @Override public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&STOP.equals(intent.getAction())){stopNavigation();return START_NOT_STICKY;}new NavSessionStore(this).start();startForeground(NOTICE,notification("正在获取定位…"));animation.removeCallbacks(headingFrame);animation.post(headingFrame);startLocations();return START_STICKY;}
    private void startLocations(){try{if(rotationSensor!=null)sensors.registerListener(this,rotationSensor,SensorManager.SENSOR_DELAY_UI);Location best=null;for(String provider:locations.getProviders(true)){Location candidate=locations.getLastKnownLocation(provider);if(candidate!=null&&(best==null||candidate.getTime()>best.getTime()))best=candidate;}if(best!=null)onLocationChanged(best);locations.requestLocationUpdates(LocationManager.GPS_PROVIDER,1500,2,this,Looper.getMainLooper());locations.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,3000,5,this,Looper.getMainLooper());}catch(SecurityException e){stopNavigation();}}
    @Override public void onLocationChanged(Location l){lastLocation=l;JSONObject route=new RouteStore(this).route();JSONArray points=route.optJSONArray("points");if(points==null||points.length()<2)return;Progress progress=progress(points,route.optJSONArray("maneuvers"),l.getLatitude(),l.getLongitude());boolean off=progress.crossTrack>55;offRouteFixes=off?offRouteFixes+1:0;boolean confirmed=offRouteFixes>=3;long now=System.currentTimeMillis();float speed=l.hasSpeed()?l.getSpeed():0;boolean moving=l.hasBearing()&&speed>1.4f;float rawBearing=moving?l.getBearing():(now-sensorTime<3000&&!Float.isNaN(sensorBearing)?sensorBearing:progress.routeBearing);targetBearing=rawBearing;if(Float.isNaN(displayBearing))displayBearing=rawBearing;int originalDistance=Math.max(1,route.optInt("distance",progress.remaining));int originalDuration=route.optInt("duration",0);int eta=originalDuration>0?Math.round(originalDuration*(progress.remaining/(float)originalDistance)):0;new NavSessionStore(this).update(l.getLatitude(),l.getLongitude(),displayBearing,speed,progress.index,progress.nextIndex,progress.nextDistance,progress.remaining,eta,progress.instruction,progress.road,confirmed);if(now-lastWidget>1200){lastWidget=now;NavWidget.publish(this);updateNotification(progress,confirmed);}SceneStore scene=new SceneStore(this);if(now-lastScene>12000&&(!scene.ready()||distance(scene.lat(),scene.lon(),l.getLatitude(),l.getLongitude())>650)){lastScene=now;io.execute(()->{try{JSONObject data=OfflineSceneSource.fetch(this,l.getLatitude(),l.getLongitude());if(data!=null){new SceneStore(this).save(data,l.getLatitude(),l.getLongitude());NavWidget.publish(this);}}catch(Exception e){android.util.Log.w("MotoNav","dynamic offline scene",e);}});}if(confirmed&&now-lastReroute>120000){lastReroute=now;reroute(l);}}
    @Override public void onSensorChanged(SensorEvent event){if(event.sensor.getType()!=Sensor.TYPE_ROTATION_VECTOR)return;float[] matrix=new float[9],adjusted=new float[9],orientation=new float[3];SensorManager.getRotationMatrixFromVector(matrix,event.values);int rotation=((WindowManager)getSystemService(WINDOW_SERVICE)).getDefaultDisplay().getRotation();if(rotation==Surface.ROTATION_90)SensorManager.remapCoordinateSystem(matrix,SensorManager.AXIS_Y,SensorManager.AXIS_MINUS_X,adjusted);else if(rotation==Surface.ROTATION_180)SensorManager.remapCoordinateSystem(matrix,SensorManager.AXIS_MINUS_X,SensorManager.AXIS_MINUS_Y,adjusted);else if(rotation==Surface.ROTATION_270)SensorManager.remapCoordinateSystem(matrix,SensorManager.AXIS_MINUS_Y,SensorManager.AXIS_X,adjusted);else System.arraycopy(matrix,0,adjusted,0,9);SensorManager.getOrientation(adjusted,orientation);float raw=(float)((Math.toDegrees(orientation[0])+360)%360);if(lastLocation!=null){GeomagneticField field=new GeomagneticField((float)lastLocation.getLatitude(),(float)lastLocation.getLongitude(),(float)lastLocation.getAltitude(),System.currentTimeMillis());raw=(raw+field.getDeclination()+360)%360;}if(Float.isNaN(sensorBearing))sensorBearing=raw;else sensorBearing=(sensorBearing+angleDelta(sensorBearing,raw)*.22f+360)%360;sensorTime=System.currentTimeMillis();if(lastLocation==null||!lastLocation.hasSpeed()||lastLocation.getSpeed()<=1.4f){targetBearing=sensorBearing;if(Float.isNaN(displayBearing))displayBearing=sensorBearing;}}
    @Override public void onAccuracyChanged(Sensor sensor,int accuracy){}
    private void reroute(Location l){io.execute(()->{try{RouteStore store=new RouteStore(this);double dLat=Double.parseDouble(store.destLat()),dLon=Double.parseDouble(store.destLon());JSONObject route=AmapRouteSource.fetch(store.key(),l.getLatitude(),l.getLongitude(),dLat,dLon);route.put("destination",store.address());store.save(route);offRouteFixes=0;NavWidget.publish(this);}catch(Exception e){android.util.Log.w("MotoNav","limited reroute",e);}});}
    private Progress progress(JSONArray pts,JSONArray maneuvers,double lat,double lon){int nearest=0;double best=Double.MAX_VALUE;for(int i=0;i<pts.length();i++){JSONArray q=pts.optJSONArray(i);if(q==null)continue;double d=distance(lat,lon,q.optDouble(0),q.optDouble(1));if(d<best){best=d;nearest=i;}}int remaining=0;for(int i=nearest;i<pts.length()-1;i++)remaining+=Math.round((float)distance(pts.optJSONArray(i).optDouble(0),pts.optJSONArray(i).optDouble(1),pts.optJSONArray(i+1).optDouble(0),pts.optJSONArray(i+1).optDouble(1)));int next=pts.length()-1;String instruction="到达目的地",road="";if(maneuvers!=null)for(int i=0;i<maneuvers.length();i++){JSONObject m=maneuvers.optJSONObject(i);if(m!=null&&m.optInt("point",0)>nearest){next=m.optInt("point");instruction=m.optString("instruction",instruction);road=m.optString("road","");break;}}int nextDistance=0;for(int i=nearest;i<Math.min(next,pts.length()-1);i++)nextDistance+=Math.round((float)distance(pts.optJSONArray(i).optDouble(0),pts.optJSONArray(i).optDouble(1),pts.optJSONArray(i+1).optDouble(0),pts.optJSONArray(i+1).optDouble(1)));float routeBearing=0;if(nearest<pts.length()-1){JSONArray a=pts.optJSONArray(nearest),b=pts.optJSONArray(nearest+1);routeBearing=bearing(a.optDouble(0),a.optDouble(1),b.optDouble(0),b.optDouble(1));}return new Progress(nearest,next,nextDistance,remaining,(float)best,routeBearing,instruction,road);}
    private float bearing(double aLat,double aLon,double bLat,double bLon){double y=Math.sin(Math.toRadians(bLon-aLon))*Math.cos(Math.toRadians(bLat)),x=Math.cos(Math.toRadians(aLat))*Math.sin(Math.toRadians(bLat))-Math.sin(Math.toRadians(aLat))*Math.cos(Math.toRadians(bLat))*Math.cos(Math.toRadians(bLon-aLon));return (float)((Math.toDegrees(Math.atan2(y,x))+360)%360);}
    private double distance(double aLat,double aLon,double bLat,double bLon){double y=(bLat-aLat)*111320.0,x=(bLon-aLon)*111320.0*Math.cos(Math.toRadians((aLat+bLat)/2));return Math.hypot(x,y);}
    private void updateNotification(Progress p,boolean off){NotificationManager nm=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);nm.notify(NOTICE,notification(off?"已偏离路线，准备重新规划":p.instruction+" · "+p.nextDistance+"m"));}
    private Notification notification(String text){Intent open=new Intent(this,NavActivity.class);PendingIntent content=PendingIntent.getActivity(this,1,open,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Intent stop=new Intent(this,NavForegroundService.class).setAction(STOP);PendingIntent stopPi=PendingIntent.getService(this,2,stop,PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,CHANNEL):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_menu_mylocation).setContentTitle("MOTO NAV · 导航中").setContentText(text).setContentIntent(content).setOngoing(true).addAction(new Notification.Action.Builder(null,"结束导航",stopPi).build()).build();}
    private float angleDelta(float from,float to){return (to-from+540)%360-180;}
    private void stopNavigation(){animation.removeCallbacks(headingFrame);try{locations.removeUpdates(this);}catch(Exception ignored){}if(sensors!=null)sensors.unregisterListener(this);new NavSessionStore(this).stop();NavWidget.publish(this);stopForeground(true);stopSelf();}
    @Override public void onDestroy(){animation.removeCallbacks(headingFrame);try{locations.removeUpdates(this);}catch(Exception ignored){}if(sensors!=null)sensors.unregisterListener(this);io.shutdownNow();super.onDestroy();}
    @Override public android.os.IBinder onBind(Intent i){return null;}
    @Override public void onProviderEnabled(String p){} @Override public void onProviderDisabled(String p){} @Override public void onStatusChanged(String p,int s,Bundle b){}
    private static final class Progress{final int index,nextIndex,nextDistance,remaining;final float crossTrack,routeBearing;final String instruction,road;Progress(int i,int n,int nd,int r,float c,float b,String ins,String road){index=i;nextIndex=n;nextDistance=nd;remaining=r;crossTrack=c;routeBearing=b;instruction=ins;this.road=road;}}
}
